ALTER TABLE `chief_thread` ADD `archivedAt` integer;--> statement-breakpoint
UPDATE `chief_message` SET `projectId` = (SELECT `u`.`projectId` FROM `chief_message` `u` WHERE `u`.`threadId` = `chief_message`.`threadId` AND `u`.`role` = 'user' AND `u`.`id` NOT LIKE 'user-%' AND (`u`.`createdAt` < `chief_message`.`createdAt` OR (`u`.`createdAt` = `chief_message`.`createdAt` AND `u`.`rowid` < `chief_message`.`rowid`)) ORDER BY `u`.`createdAt` DESC, `u`.`rowid` DESC LIMIT 1) WHERE `chief_message`.`projectId` IS NULL AND (`chief_message`.`role` <> 'user' OR `chief_message`.`id` LIKE 'user-%') AND `chief_message`.`threadId` NOT LIKE 'chief-digest-%';--> statement-breakpoint
UPDATE `chief_message` SET `projectId` = COALESCE(`chief_message`.`projectId`, (SELECT `t`.`projectId` FROM `chief_thread` `t` WHERE `t`.`id` = `chief_message`.`threadId`)), `threadId` = COALESCE((SELECT `k`.`id` FROM `chief_thread` `k` WHERE `k`.`chiefId` = (SELECT `t`.`chiefId` FROM `chief_thread` `t` WHERE `t`.`id` = `chief_message`.`threadId`) AND `k`.`id` NOT LIKE 'chief-digest-%' ORDER BY `k`.`projectId` IS NOT NULL, `k`.`updatedAt` DESC, `k`.`id` DESC LIMIT 1), `chief_message`.`threadId`) WHERE `chief_message`.`threadId` NOT LIKE 'chief-digest-%' AND EXISTS (SELECT 1 FROM `chief_thread` `e` WHERE `e`.`id` = `chief_message`.`threadId`);--> statement-breakpoint
UPDATE `step` SET `buildId` = COALESCE((SELECT `k`.`id` FROM `chief_thread` `k` WHERE `k`.`chiefId` = (SELECT `t`.`chiefId` FROM `chief_thread` `t` WHERE `t`.`id` = `step`.`buildId`) AND `k`.`id` NOT LIKE 'chief-digest-%' ORDER BY `k`.`projectId` IS NOT NULL, `k`.`updatedAt` DESC, `k`.`id` DESC LIMIT 1), `step`.`buildId`) WHERE `step`.`kind` = 'chief' AND `step`.`status` IN ('pending', 'waiting_quota') AND `step`.`buildId` NOT LIKE 'chief-digest-%';--> statement-breakpoint
UPDATE `chief` SET `watches` = (SELECT json_group_array(json_set(`w`.`value`, '$.threadId', CASE WHEN json_extract(`w`.`value`, '$.threadId') NOT LIKE 'chief-digest-%' THEN COALESCE((SELECT `k`.`id` FROM `chief_thread` `k` WHERE `k`.`chiefId` = `chief`.`id` AND `k`.`id` NOT LIKE 'chief-digest-%' ORDER BY `k`.`projectId` IS NOT NULL, `k`.`updatedAt` DESC, `k`.`id` DESC LIMIT 1), json_extract(`w`.`value`, '$.threadId')) ELSE json_extract(`w`.`value`, '$.threadId') END)) FROM json_each(`chief`.`watches`) `w`) WHERE json_array_length(`chief`.`watches`) > 0;--> statement-breakpoint
UPDATE `chief` SET `wakes` = (SELECT json_group_array(json_set(`w`.`value`, '$.threadId', CASE WHEN json_extract(`w`.`value`, '$.threadId') NOT LIKE 'chief-digest-%' THEN COALESCE((SELECT `k`.`id` FROM `chief_thread` `k` WHERE `k`.`chiefId` = `chief`.`id` AND `k`.`id` NOT LIKE 'chief-digest-%' ORDER BY `k`.`projectId` IS NOT NULL, `k`.`updatedAt` DESC, `k`.`id` DESC LIMIT 1), json_extract(`w`.`value`, '$.threadId')) ELSE json_extract(`w`.`value`, '$.threadId') END)) FROM json_each(`chief`.`wakes`) `w`) WHERE json_array_length(`chief`.`wakes`) > 0;--> statement-breakpoint
UPDATE `chief_thread` SET `archivedAt` = CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER) WHERE `chief_thread`.`id` NOT LIKE 'chief-digest-%' AND `chief_thread`.`id` <> (SELECT `k`.`id` FROM `chief_thread` `k` WHERE `k`.`chiefId` = `chief_thread`.`chiefId` AND `k`.`id` NOT LIKE 'chief-digest-%' ORDER BY `k`.`projectId` IS NOT NULL, `k`.`updatedAt` DESC, `k`.`id` DESC LIMIT 1);--> statement-breakpoint
UPDATE `chief_thread` SET `projectId` = NULL, `title` = 'Coordinator' WHERE `chief_thread`.`archivedAt` IS NULL AND `chief_thread`.`id` NOT LIKE 'chief-digest-%';--> statement-breakpoint
UPDATE `chief_thread` SET `activeRun` = '{"phase":"chief"}' WHERE `chief_thread`.`activeRun` IS NULL AND `chief_thread`.`id` IN (SELECT `s`.`buildId` FROM `step` `s` WHERE `s`.`kind` = 'chief' AND `s`.`status` IN ('pending', 'waiting_quota', 'claimed'));--> statement-breakpoint
UPDATE `chief_thread` SET `activeRun` = NULL WHERE `chief_thread`.`archivedAt` IS NOT NULL AND `chief_thread`.`id` NOT IN (SELECT `s`.`buildId` FROM `step` `s` WHERE `s`.`kind` = 'chief' AND `s`.`status` IN ('pending', 'waiting_quota', 'claimed'));--> statement-breakpoint
CREATE UNIQUE INDEX `chief_thread_coordinator_unique` ON `chief_thread` (`chiefId`) WHERE "chief_thread"."archivedAt" is null and "chief_thread"."id" not like 'chief-digest-%';
